WITH with_prev AS (SELECT *, LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) AS prev_event_time FROM web_events), gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_burst FROM with_prev) SELECT id, session_id, page, event_time, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps;
